import java.util.ArrayList;
import java.util.List;
import java.util.Set;

public final class Solution {
    private Solution() {}

    public static final class Asset {
        private final long id;
        private final String group;
        private final String name;

        public Asset(long id, String group, String name) {
            if (id <= 0 || group == null || group.isEmpty() || name == null || name.isEmpty()) throw new IllegalArgumentException();
            this.id = id;
            this.group = group;
            this.name = name;
        }

        public long getId() { return id; }
        public String getGroup() { return group; }
        public String getName() { return name; }
    }

    public static List<Asset> selectAssets(List<Asset> assets, Set<String> groups) {
        validate(assets);
        if (groups == null || groups.contains(null)) throw new IllegalArgumentException();
        List<Asset> result = new ArrayList<>();
        for (Asset asset : assets) {
            if (groups.isEmpty() || groups.contains(asset.getGroup())) result.add(asset);
        }
        return result;
    }

    public static Asset findAsset(List<Asset> assets, long id) {
        validate(assets);
        if (id <= 0) throw new IllegalArgumentException();
        for (Asset asset : assets) if (asset.getId() == id) return asset;
        return null;
    }

    private static void validate(List<Asset> assets) {
        if (assets == null) throw new IllegalArgumentException();
        for (Asset asset : assets) if (asset == null) throw new IllegalArgumentException();
    }
}
